def bank_rollback(balance, transactions):
    """
    Apply a list of transactions in order to an initial bank balance.
    If any transaction causes the balance to go below zero, reject all transactions.

    Args:
        balance (float/int): Initial balance
        transactions (list of float/int): List of transaction amounts (positive for deposits, negative for withdrawals)

    Returns:
        tuple: (final_balance, success_flag) where success_flag is True if all transactions completed successfully, False otherwise.
    """
    current_balance = balance

    for transaction in transactions:
        current_balance += transaction
        if current_balance < 0:
            return (balance, False)

    return (current_balance, True)
